 {id:'p8',name:'Side Mirror Assembly',category:'Body Parts',price:38500,wholesalePrice:27900,stock:30,moq:6,seller:'XYZ Auto Distribution',sellerType:'wholesaler',location:'Lagos',image:'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&fit=crop&w=900&q=80',fit:'Selected Toyota models',tag:'Trade price'}
